function make(d: HarmorDiff): GenInstance {
  const inst = gen.create(44100, 88, { sample: () => undefined });
  inst.setParams(normalizeHarmor({ ...expandDiff(d) }) as Record<string, unknown>);
  // the test host plays at 140 BPM (plug tempo -> phaser speed, 0xcfa60)
  const plug = (inst as any).plug;
  plug.tempo = 140;
  for (const pt of plug.parts) phaserTempo(plug, pt);
  return inst;
}

function noteOn(inst: GenInstance): void {
  const lv = newLevels(); lv.pitch = 6000; lv.vol = (Math.pow(11, 1) - 1) / 10;
  const init = newLevels(); init.pitch = 6000; init.vol = lv.vol;
  inst.noteOn!({ id: 1, key: 60, velocity: 100, release: 64, color: 0, length: Infinity, frame: 0, init, levels: lv } as GenNote, 0);
}

const part0 = (inst: GenInstance): any => (inst as any).plug.parts[0];

describe('harmor filters: shapes (0xcc010)', () => {
  it('builds every built-in table bit for bit', () => {
    const pt = part0(make({}));
    for (const [type, count, x14, y18, z1c, scale, s24, act, vals] of SHAPES) {
      const S = new Shape(4097);
      buildShape(pt, S, type);
      expect([type, S.count, S.x14, S.y18, S.z1c, S.scale, S.s24, S.flags]).toEqual([type, count, Math.fround(x14), y18, z1c, scale, s24, act]);
      for (let k = 0; k < vals.length; k += 2) expect([type, vals[k], S.tab[vals[k]]]).toEqual([type, vals[k], Math.fround(vals[k + 1])]);
    }
  });

  it('main shape (Global EQ): highest partial 17637.5 Hz, partials above it muted', () => {
    const pt = part0(make({}));
    expect(pt.maxFreq).toBe(17637.515625);
    const logf = new Float32Array([Math.log2(261.6), Math.log2(16000), Math.log2(17500), Math.log2(18000), 4, 0, 0, 0]);
    const out = new Float32Array(8);
    mainShape(pt, logf, out, 8);
    expect(out[0]).toBe(1);
    expect(out[1]).toBe(1);
    expect(out[2]).toBeGreaterThan(0);
    expect(out[2]).toBeLessThan(0.01);
    expect(out[3]).toBe(0);
    expect(out[4]).toBe(0);
  });

  it('the "Freq" phaser type makes the phaser shape map bipolar (0x444350)', () => {
    const inst = make({ A: { phType: 9 } });
    expect(part0(inst).maps[15].offset).toBe(0.5);
    expect(part0(inst).shp.ph.type).toBe(209);
    inst.setParams(normalizeHarmor({ ...expandDiff({ A: { phType: 10 } }) }) as Record<string, unknown>);
    expect(part0(inst).maps[15].offset).toBe(0);
    expect(part0(inst).shp.ph.type).toBe(210);
  });
});

describe('harmor filters: filter / resonance / phaser units vs FL 2026', () => {
  for (const c of VOICES) {
    it(c.name, () => {
      const inst = make({ A: c.A as any, G: c.G as any, p: c.p });
      noteOn(inst);
      const ctx = { sampleRate: 44100, blockSize: 88, tempo: 140, ppq: 96, playing: true, pos: 0, songMode: false, track: 0 };
      const L = new Float32Array(88), R = new Float32Array(88);
      for (let b = 0; b <= 12; b++) { L.fill(0); R.fill(0); inst.render!(L, R, 88, ctx); }
      const v = (inst as any).live[0];
      expect(v.sb.count).toBe(c.n);
      let sum = 0;
      for (let i = 0; i < c.n; i++) sum += v.sb.amps[i];
      for (const [i, x] of c.v) expect([i, v.sb.amps[i]]).toEqual([i, Math.fround(x)]);
      expect(sum).toBe(c.sum);
    });
  }
});
